from pathlib import Path
P=Path(__file__).resolve().parents[1]/'week11'/'week11.qmd'
slides=[]
def fig(name,h='11em',caption='',tall=False):
 return f'<div class="w11-figure{ " tall" if tall else ""}" style="height:{h};"><img src="figures/{name}.svg" alt="{name.replace("_"," ")}"></div>'+(f'<div class="w11-under">{caption}</div>' if caption else '')
def card(title,body,variant='uncertainty'):
 return f'<div class="w11-card {variant}"><strong>{title}</strong><span>{body}</span></div>'
def cards(items,n=None):
 return f'<div class="w11-cards" style="--n:{n or len(items)};">'+''.join(card(*i) for i in items)+'</div>'
def note(txt,warning=False):return f'<div class="{"warning-box" if warning else "definition-box"}"><p>{txt}</p></div>'
def small(s):return '<div class="w11-under">'+s+'</div>'
def big(s):return '<div class="w11-math">'+s+'</div>'
def table(headers,rows):
 return '<div class="w11-table" style="--n:%d;">'%len(headers)+''.join('<div class="head">'+x+'</div>' for x in headers)+''.join('<div>'+str(c)+'</div>' for row in rows for c in row)+'</div>'
def slide(title,body='',cls='concept-slide'):
 slides.append(f'## {title} {{.{cls}}}\n\n{body.strip()}\n')
def b(title):return '<div class="eyebrow">'+title+'</div>'
def lab(name,controls,svg,outs,subtitle=''):
 controls_str=''.join(controls)
 outputs=f'<div class="w11-readout" style="--n:{len(outs)};">'+''.join(f'<div class="w11-output"><span>{l}</span><strong id="{ident}">—</strong></div>' for l,ident in outs)+'</div>'
 return f'<div class="w11-lab" id="{name}"><div class="w11-controls">{controls_str}</div><div class="w11-visual"><svg id="{svg}" class="w11-svg" viewBox="0 0 900 460" aria-label="{subtitle or name}"></svg>{outputs}</div></div>'
def rng(ident,title,lo,hi,val,step=1,labid=None):
 return f'<label class="w11-control">{title} <strong id="{labid or ident+"V"}">{val}</strong><input id="{ident}" type="range" min="{lo}" max="{hi}" value="{val}" step="{step}"></label>'
def buttons(items):return '<div class="w11-btn-row">'+''.join(f'<button class="w11-btn {"secondary" if i>0 else ""}" id="{ident}" type="button">{label}</button>' for i,(ident,label) in enumerate(items))+'</div>'
def quiz(k,q,opts):
 return f'<div class="w11-quiz" data-q="{k}"><div class="w11-quiz-q">{q}</div><div class="w11-choices">'+''.join(f'<button type="button" class="w11-choice" data-choice="{chr(65+i)}">{chr(65+i)}. {o}</button>' for i,o in enumerate(opts))+'</div><div class="w11-feedback">Choose one response.</div></div>'

slide('Time, survival, smoothing',b('Week 11')+'<div class="w11-hero">What changes when observations have <strong>temporal structure?</strong></div>','title-slide')
slide('The unifying change',b('From exchangeable observations to a path through time')+'<div class="w11-flow"><div><strong>Trajectory</strong><span>What happened?</span></div><div><strong>Dependence</strong><span>How is today related to yesterday?</span></div><div><strong>Events</strong><span>How long until something occurs?</span></div><div><strong>Prediction</strong><span>What happens next, with uncertainty?</span></div></div>'+note('The order of measurements can contain information. Ignoring it may yield overly confident or misleading answers.'))
slide('Why is time not just another x-variable?',b('Two scatter plots may look equally convincing')+fig('time_vs_independent','12.0em')+small('For independent cells, the order is arbitrary; for successive IL-6 measurements from a patient, order is part of the experiment.'))
slide('Longitudinal versus time-series data',cards([('Longitudinal','Many subjects; each may be measured repeatedly at several visits.','observed'),('Time series','One process observed in order; adjacent observations can be dependent.','model'),('Both','Temporal dependence, irregular sampling and missing visits need attention.','uncertainty')])+note('Repeated measurements do not logically imply autocorrelation, but they often do in biomedical settings.'))
slide('Three common response shapes',fig('trajectory_types','11.8em')+small('Growth toward a plateau · elimination/decay · peak and recovery. Each requires different summary questions.'))
slide('Plot individual trajectories first',b('Drug A versus Drug B · n = 10 per arm')+fig('pk_group_trajectories','12em')+small('Faint curves are patients; bold curves are sample means; shaded bands illustrate 95% pointwise mean CIs.'))
slide('Why not six separate t tests?',cards([('Repeated measures','Each person contributes a correlated trajectory.','observed'),('Multiplicity','Comparing each time point repeatedly creates many opportunities for false alarms.','warning'),('Missing pattern','An isolated p-value can conceal timing, amplitude and overall exposure.','model')])+note('A scientifically meaningful <strong>trajectory-level endpoint</strong> can sometimes replace a much more complicated analysis.'))
slide('Reduce a whole trajectory to interpretable endpoints',table(['Question','Summarize with','Interpretation'],[['Overall exposure','AUC, time average','Depends on observation window and baseline'],['Peak response','Maximum / minimum','Response magnitude'],['When is the peak?','$t_{\max}$','Timing of response'],['Change / decay rate','Slope or rate constant','Kinetic behavior'],['How long above target?','Time above threshold','Duration of target attainment']])+small('Prespecify endpoints; changing definitions after seeing data introduces bias.'))
slide('Pharmacokinetics: the shape has meaning',fig('pk_anatomy','11.8em')+small('AUC = area under concentration versus time; $C_{\max}$ = peak concentration; $t_{\max}$ = peak time.'))
slide('PK quantities should not be confused',cards([('AUC','Total concentration–time exposure, not administered dose.','uncertainty'),('Time above threshold','Especially important for time-dependent antimicrobial pharmacodynamics.','estimate'),('Clearance','Under a simple one-compartment model with first-order elimination, $CL=k V_d$.','model')])+note('The elimination-rate constant $k$ has units of inverse time. Zero-order and first-order elimination follow different kinetic equations.'))
slide('An HPLC chromatogram is also time-indexed',fig('chromatogram','11.5em')+small('Peak position = retention time; integrated detector response = peak area. Calibration is required to infer analyte amount.'))
slide('Can we remove time by design?',b('Repeated blood pressure during one clinic visit')+fig('bp_stabilization','11.3em')+note('If an acquisition protocol <strong>prespecifies</strong> a stabilization phase, averaging later readings can yield one patient-level endpoint. Do not discard early values post hoc merely because they differ.'))
slide('Regression to the mean',b('Selection on extreme measurements')+cards([('At screening','A patient is selected partly because of a genuinely high value, partly because of random positive noise.','observed'),('At repeat testing','The same person often has a less extreme observed value even without effective treatment.','model')])+big('$Y_{it}=\mu_i+\varepsilon_{it}$')+small('Persistent person-specific level $\mu_i$ + measurement-to-measurement fluctuation $\varepsilon_{it}$.'))
rtm_controls=[rng('rtmTop','Select top % of original readings',2,30,10,1),buttons([('rtmResample','Repeat selected'),('rtmNew','New cohort'),('rtmReset','Reset')]),'<div class="w11-micro">Same selected people remain highlighted. Only their repeat measurement changes; the cohort is not reselected.</div>']
slide('Lab: watch regression to the mean',lab('rtmWidget',rtm_controls,'rtmSvg',[('Initial selected mean','rtmOldMean'),('Most recent mean','rtmNewMean'),('Selection size','rtmCount')],'Regression to the mean: screen top measurements and repeat'))
slide('The placebo-group surprise',cards([('Screen','Recruit only people with unusually elevated blood pressure.','observed'),('Follow up','Even without an active effect, their average may decrease on repeat measurement.','model'),('Interpret','A control arm helps separate spontaneous variation from a treatment effect.','estimate')])+note('A reduction after treatment <strong>alone</strong> is not proof that the treatment caused it.',True))
slide('A fitted time curve can still be useful',cards([('Regression','Fit a prespecified exponential, logistic or other trajectory.','estimate'),('Coefficients','Compare rate, peak, delay, plateau, or asymptote.','model'),('Danger','Repeated observations can have correlated residuals.','warning')])+fig('temporal_band_warning','8.0em'))
slide('Correlation changes uncertainty',b('Same trend; different standard-error assumptions')+fig('temporal_band_warning','11.5em')+small('Bands intentionally schematic. The broader band illustrates why independence assumptions can understate uncertainty; actual widths depend on the fitted correlation model.'))
slide('Autocorrelation means a lag matters',big('$\rho(k)=\operatorname{Corr}(Y_t,Y_{t-k})$')+cards([('Lag 1','The similarity of consecutive values.','observed'),('Lag 6','The similarity of values separated by six time steps.','uncertainty'),('Differencing','$Y_t-Y_{t-1}$ is a separate transformation, not the definition of autocorrelation.','model')]))
slide('Three contrasting dependence structures',fig('acf_structures','12.2em')+small('AR(1): correlation decays across lags. Compound symmetry: an illustrative equal within-subject correlation. White noise: no serial correlation.'))
slide('A random walk is not independent observations',cards([('Steps','Independent changes: $X_{t+1}-X_t=\epsilon_t$.','observed'),('Positions','Accumulated history: $X_t=\sum_{j\le t}\epsilon_j$.','model'),('Consequence','Even independent steps can create strongly dependent position values.','uncertainty')])+note('An ideal symmetric lattice walk in 1D or 2D returns with probability 1; in 3D it may return, but the return probability is below 1.'))
slide('Random walk: 2D versus 3D',b('An animation of accumulated chance')+'<video class="w11-video" controls muted loop playsinline preload="metadata" poster="figures/randomwalk_still.svg"><source src="media/random_walk_2d_3d.mp4" type="video/mp4"></video>'+small('An example path, not a proof. The recurrence distinction concerns the probability of ever returning to the starting lattice point.'))
slide('Time-series decomposition',b('Trend + seasonal component + slower cycle + noise')+fig('decomposition','12.5em')+small('The components are modeling choices, not automatically identifiable features of every signal.'))
slide('Smoothing: what should survive?',cards([('Signal','Structured variation relevant to the scientific question.','estimate'),('Noise','Variation we hope to attenuate, which may itself contain meaningful events.','observed'),('Trade-off','Aggressive smoothing erases sharp peaks and can bias maxima or event timing.','warning')])+note('Choose a smoother with the scientific endpoint in mind, not only how pleasing the final curve looks.'))
slide('Moving average',big('$\widehat y_t=\dfrac{1}{2k+1}\sum_{j=-k}^{k}y_{t+j}$')+cards([('Window width','A wider window attenuates short-term fluctuation.','estimate'),('Cost','Sharp peaks flatten; edge values need special handling.','warning')])+small('A simple local average is not a regression model for the underlying mechanism.'))
slide('Savitzky–Golay: local polynomial fitting',cards([('Within each window','Fit a low-degree polynomial to nearby observed points.','observed'),('At the window center','Use the fitted central value; then slide the window.','estimate'),('In practice','Retains local peaks and derivatives better than a boxcar average in many settings.','model')])+note('Polynomial degree must be smaller than the odd window length; excessive degree may overfit noise.'))
slide('Smoothing splines: let curvature cost something',big('$\min_f\;\sum_i (y_i-f(t_i))^2 + \lambda\!\int [f\prime\prime(t)]^2\,dt$')+cards([('Small $\lambda$','Fit follows data more closely; can appear jagged.','observed'),('Large $\lambda$','Favors less curvature; approaches a straight line.','model'),('Natural boundaries','The second derivative vanishes at the endpoints; slope need not vanish.','uncertainty')]))
sm_controls=['<label class="w11-control">Method<select id="smMethod"><option value="mean">Moving average</option><option value="sg">Savitzky–Golay</option><option value="spline">Smoothing spline proxy</option></select></label>',rng('smWindow','Odd window size',3,21,7,2),rng('smDegree','Polynomial degree',1,4,3,1),rng('smLambda','Curvature penalty (log₁₀ λ)',-4,3,-1,.25),buttons([('smGcv','Choose λ by GCV'),('smNew','New noise')]),'<div class="w11-micro">Spline panel uses a finite-difference curvature penalty, a close discrete analogue; GCV selects its penalty.</div>']
slide('Lab: compare smoothing methods on the same data',lab('smoothWidget',sm_controls,'smoothSvg',[('Method','smMethodOut'),('RMSE to truth','smRmseOut'),('Selected λ','smLambdaOut')],'Compare moving average, local polynomials and curvature smoothing'))
slide('Filtering asks a different question',cards([('Smoothing','Attenuate fluctuations locally or by roughness penalty.','estimate'),('Fourier view','Express the signal as a superposition of frequencies.','uncertainty'),('Filtering','Keep or attenuate frequency ranges, then reconstruct.','model')])+small('A sudden event spreads energy across frequencies; suppressing high frequencies can blur clinically important spikes.'))
slide('A signal can be made from sinusoidal parts',big('$y(t)=\sum_j A_j\sin(2\pi f_jt+\phi_j)$')+cards([('Amplitude $A$','Controls how strong a component is.','observed'),('Frequency $f$','Controls cycles per unit time.','uncertainty'),('Phase $\phi$','Shifts the component through time; magnitude need not change.','model')]))
ft_controls=[rng('ftA1','Component 1 amplitude',0,3,2,.1),rng('ftF1','Component 1 frequency',1,15,3,1),rng('ftP1','Component 1 phase',0,6.28,0,.2),rng('ftA2','Component 2 amplitude',0,3,1.2,.1),rng('ftF2','Component 2 frequency',1,15,8,1),rng('ftP2','Component 2 phase',0,6.28,1.2,.2),'<label class="w11-control">Third component<select id="ftThird"><option value="off">Off</option><option value="on">On · amplitude 0.8, frequency 12</option></select></label>']
slide('Lab: a Fourier magnitude spectrum',lab('fourierWidget',ft_controls,'fourierSvg',[('Dominant frequency','ftDom'),('Peak magnitude','ftMag')],'Wave components and discrete Fourier magnitudes'))
slide('Frequency-selective filtering',fig('fourier_filter','11.8em')+note('Remove unwanted bands, but beware of losing slow biological trends or fast clinically meaningful transients.'))
slide('The measurement system can blur hidden events',b('Convolution: an instrument response shapes what we see')+big('$y(t)=(x*h)(t)+\varepsilon(t)$')+cards([('Hidden input $x$','A neural impulse or narrow chromatographic peak.','observed'),('Response $h$','A slower hemodynamic or instrument impulse response.','model'),('Observed $y$','Overlapping, blurred responses plus noise.','uncertainty')]))
slide('Deconvolution: reconstruct, never magically undo',fig('deconvolution','11.6em')+small('Regularization is required because division by a near-zero Fourier component amplifies noise. Exact millisecond timing cannot generally be recovered from a slow fMRI signal.'))
slide('A different time question: time until an event',cards([('Event','Death, relapse, adverse effect, or another defined endpoint.','observed'),('Start time','Diagnosis, first dose, randomization or enrollment.','model'),('Complication','Some people have not had an event by their last known follow-up.','uncertainty')])+note('Survival analysis is about <strong>time to event</strong>, not necessarily death.'))
slide('Censoring differs from truncation',table(['Mechanism','What is known?'],[['Right censor','Event time exceeds the final observation time'],['Left censor','Event happened before the first reliable observation'],['Interval censor','Event happened inside an observed interval'],['Left truncation','Person enters only after surviving past entry time'],['Right truncation','Selection requires an event before a sampling cutoff']]))
slide('What timelines actually look like',fig('censoring_truncation','12.1em')+small('Cross: observed event; tick: right censor; other rows show differing information/selection mechanisms.'))
slide('Kaplan–Meier: multiply conditional survival',big('$\widehat S(t)=\prod_{t_i\le t}\left(1-\dfrac{d_i}{r_i}\right)$')+cards([('$r_i$','Number still at risk immediately before event time $t_i$.','observed'),('$d_i$','Number with the event at that time.','warning'),('$1-d_i/r_i$','Probability of surviving this event time, conditional on the risk set.','estimate')])+small('Right censoring reduces subsequent risk sets but does not itself cause a drop in the KM curve.'))
slide('Work out the first few KM steps',table(['Time','At risk $r_i$','Events $d_i$','Conditional factor','Cumulative $\hat S(t)$'],[['Month 1','8','1','$7/8$','$7/8 = 0.875$'],['Month 2','7','2','$5/7$','$(7/8)(5/7)=0.625$'],['Month 3','4','1','$3/4$','$0.625(3/4)=0.469$']])+small('Illustrative risk sets: one person was censored after month 2 but before month 3. The product gives cumulative survival.'))
slide('Compare two Kaplan–Meier curves',fig('km_two_groups','12.1em')+small('Hypothetical therapies; right-censor marks (+). Confidence bands are schematic, not formal Greenwood bands.'))
slide('A survival plot does not by itself prove a difference',cards([('Visual evidence','Step heights and separation suggest differences in event timing.','observed'),('Inference','A log-rank test or Cox model addresses a defined comparison.','estimate'),('Limitations','Censoring, competing events and non-proportional hazards matter.','warning')])+note('Median survival is the first time at which estimated $S(t)$ reaches or falls below 0.5; it may be unreached.'))
slide('Hazard: the danger conditional on survival',big('$h(t)=\lim_{\Delta t\to0}\dfrac{P(t\le T<t+\Delta t\mid T\ge t)}{\Delta t}$')+cards([('Survival $S(t)$','Probability event time is later than $t$.','observed'),('CDF $F(t)$','$1-S(t)$: probability the event has occurred by $t$.','estimate'),('Hazard $h(t)$','An instantaneous conditional event rate, not a probability.','warning')]))
slide('Hazard can rise, fall, or stay constant',fig('hazard_shapes','11.8em')+small('Illustrative mechanisms: wear-out, early vulnerability, and memoryless exponential survival.'))
slide('The area under survival measures time',big('$E[T]=\int_0^\infty S(t)\,dt$')+note('With incomplete follow-up, <strong>restricted mean survival time</strong> (RMST) integrates only to a prespecified horizon $\tau$.')+cards([('Survival','How much of the population remains event-free?','observed'),('Hazard','How intense is the instantaneous event rate?','model')]))
slide('Survival curves can also be modeled parametrically',fig('survival_families','11.4em')+small('Different distributions imply different time-dependent hazards. Model choice is substantive, not decorative.'))
slide('Cox regression keeps baseline hazard flexible',big('$h(t\mid x)=h_0(t)\exp(\beta_1x_1+\cdots+\beta_px_p)$')+cards([('Baseline hazard','Time-changing hazard at the reference covariate profile.','model'),('Exponential multiplier','Covariates multiply the instantaneous hazard.','estimate'),('Primary assumption','Covariate hazard ratios are constant over time in a proportional-hazards model.','warning')]))
slide('Same changing baseline; different hazard multipliers',fig('cox_profiles','11.9em')+small('Hazard ratio 1.8 means 80% higher instantaneous hazard (at a given time), not 80% higher probability of an event.'))
slide('What if proportional hazards fails?',cards([('Check','Curves and diagnostics may suggest time-varying effects.','observed'),('Alternatives','Time-varying coefficients, stratified Cox, or accelerated failure-time models.','model'),('Scope','These are honorable mentions; learn the interpretation of HR and KM first.','uncertainty')]))
slide('Missing values: fit the observed, then predict',fig('model_imputation','11.7em')+small('Predictions are estimates, not newly observed patient measurements. Imputation uncertainty must be represented for formal inference.'))
slide('No simple formula for the response curve?',b('Gaussian-process regression')+cards([('A function prior','We describe possible response curves with a mean and covariance kernel.','model'),('Nearby experiments','Can be more similar under a smooth kernel.','uncertainty'),('Posterior','Each new measurement updates both mean prediction and uncertainty.','estimate')]))
slide('A GP still makes assumptions',fig('gp_prior','10.8em')+note('The squared-exponential kernel encodes very smooth functions; periodic and rougher kernels express different beliefs. Predictions far from observations remain uncertain.'))
gp_controls=[rng('gpLength','Kernel length scale',.3,3.5,1.2,.1),'<label class="w11-control">Acquisition score<select id="gpAcq"><option value="unc">Maximum uncertainty</option><option value="ucb">Mean + 1.5 × SD</option></select></label>',buttons([('gpSuggest','Suggest next x'),('gpReset','Clear samples')]),'<div class="w11-micro">Click anywhere within the plot to sample that experimental condition. Synthetic truth is visible faintly as a teaching aid; an experimenter would not know it.</div>']
slide('Lab: the next experiment reduces uncertainty',lab('gpWidget',gp_controls,'gpSvg',[('Samples','gpN'),('Latest sample','gpLast'),('Suggested x','gpNext')],'Gaussian-process predictive mean and uncertainty on sampled x locations'))
slide('Prediction can help plan the next experiment',cards([('Explore','Sample where uncertainty is largest.','uncertainty'),('Exploit','Sample where predicted outcome is promising.','estimate'),('Balance','An acquisition function scores where the next measurement may be most useful.','model')])+note('This is the intuition behind Bayesian optimization. It is <strong>not</strong> guaranteed to find the optimum from a handful of observations.'))
slide('What if the process moves between discrete states?',b('Nosocomial infection example')+fig('markov_states','11.7em')+small('A Markov model represents transition probabilities among susceptible, infected and recovered states. Arrows are illustrative daily probabilities.'))
slide('The Markov property',big('$P(X_{t+1}=j\mid X_t=i,\mathrm{history})=P(X_{t+1}=j\mid X_t=i)$')+cards([('Memoryless','Given today’s state, yesterday adds no predictive information in this model.','model'),('Transition matrix','Each row lists possible next states; row probabilities sum to 1.','uncertainty'),('Not universal','Real infection history and immunity may require richer states or models.','warning')]))
mk_controls=[buttons([('mkDay','Tomorrow'),('mkTen','+10 days'),('mkReset','Reset patient')]),'<div class="w11-micro">Current patient path is sampled stochastically. The bars display the theoretical population-state distribution after the same number of steps.</div>']
slide('Lab: follow one patient through a Markov chain',lab('markovWidget',mk_controls,'markovSvg',[('Day','mkDayOut'),('Patient state','mkState'),('Long-run probability of infection','mkStable')],'Markov transition simulation and state probabilities'))
slide('Repeated matrix multiplication',big('$\boldsymbol\pi_{t+1}=\boldsymbol\pi_t P$')+cards([('Starting distribution','$\boldsymbol\pi_0=(1,0,0)$: all initially susceptible.','observed'),('Next day','$\boldsymbol\pi_1=\boldsymbol\pi_0P$.','estimate'),('Long run','If the chain is irreducible and aperiodic, distributions converge to a stationary vector.','model')]))
slide('Animation: approach to the stationary distribution','<video class="w11-video" controls muted loop playsinline preload="metadata"><source src="media/markov_stationary.mp4" type="video/mp4"></video>'+small('One hypothetical daily transition matrix; eventual stationarity should not be assumed for every Markov chain.'))
slide('A tiny Markov model can even generate text',cards([('Training','Count which word follows which in a small public-domain-style toy vocabulary.','observed'),('Generation','Draw each next token using the transition probabilities of the current token.','model'),('Limit','Local transitions are not genuine understanding or long-context language modeling.','warning')]))
word_controls=['<label class="w11-control">Starting word<select id="wordStart"><option value="the">the</option><option value="night">night</option><option value="soft">soft</option><option value="river">river</option><option value="stars">stars</option></select></label>',buttons([('wordGenerate','Generate new verse'),('wordReset','Reset')]),'<div class="w11-micro">Offline miniature transition table only; not trained on 1,000 actual poems or on proprietary text.</div>']
slide('Lab: a very small text generator',lab('wordWidget',word_controls,'wordSvg',[('Tokens','wordTokens'),('Unique words','wordUnique')],'Simple next-word Markov text generation')+'<div class="w11-note" id="wordText" aria-live="polite">Select a starting word and generate.</div>')
slide('The common framework',table(['What is changing?','Method introduced','Crucial caution'],[['Repeated values','Longitudinal summaries / correlation','Do not treat every visit as independent'],['Signal shape','Smoothers / frequency analysis','Removing noise can also remove signal'],['Time to event','Kaplan–Meier / Cox','Censoring and hazard ≠ probability'],['Unknown response function','Gaussian process','Kernel assumptions control prediction'],['Discrete evolving states','Markov chain','Current-state sufficiency is an assumption']]))
slide('Exercise 1: the repeated-measures trap',quiz('1','Blood pressure is recorded six times per patient. Which analysis is invalid if it ignores within-person dependence?',['Treat all readings as independent patients','Prespecify and compare one patient-level summary','Fit a model that accounts for patient clustering']))
slide('Exercise 2: a time-to-event misconception',quiz('2','At month 6, a subject has not had the event but leaves the study. In a standard KM analysis they are…',['Counted as an event at month 6','Right censored at month 6','Excluded from every earlier risk set']))
slide('Exercise 3: the wrong interpretation',quiz('3','Cox regression reports HR = 1.5. Which statement is best?',['Instantaneous event hazard is 50% greater, conditional on the model','The 10-year event probability is exactly 50% greater','Average survival time is exactly 50% shorter']))
slide('Exercise 4: what does more data buy?',quiz('4','Why can a new Gaussian-process measurement be particularly useful near an unsampled region?',['It guarantees the global optimum','It can reduce posterior uncertainty nearby, depending on the kernel','It eliminates the need to make any correlation assumptions']))
slide('Week 11 in one sentence','<div class="w11-hero">Model what time does to <strong>dependence, uncertainty, event occurrence, and prediction</strong>.</div><div class="w11-flow"><div><strong>Trajectory</strong><span>Summarize intelligently</span></div><div><strong>Dependence</strong><span>Respect correlation</span></div><div><strong>Survival</strong><span>Honor censoring</span></div><div><strong>Prediction</strong><span>Show uncertainty</span></div></div>')
slide('Next: Week 12',b('From structured models to learning from many variables')+cards([('Multivariate structure','Principal components, factors and clustering.','observed'),('Prediction','Generalization, validation and model capacity.','estimate'),('Machine learning','A wider collection of methods, not a replacement for statistical reasoning.','uncertainty')])+note('The last week asks: when patterns are high-dimensional, how can models learn without fooling us?'))

header='''---
title: "Statistics for Pharmacists"
subtitle: "Week 11 · Time, survival, smoothing"
author: "Graduate Pharmaceutical Studies"
date: ""
title-slide-attributes:
  data-footer: ""
format:
  revealjs:
    footer: "Statistics 101 · Week 11"
    scrollable: false
    transition: fade
    theme:
      - default
      - ../assets/scss/course.scss
      - ../assets/scss/week11.scss
    resources:
      - figures/**
      - media/**
      - widgets.js
---
'''
content=(header+'\n\n'.join(slides)+'\n\n<script src="widgets.js"></script>\n').encode('utf8')
for b,txt in [(8,b'\\b'),(9,b'\\t'),(11,b'\\v'),(13,b'\\r')]:
    content=content.replace(bytes([b]),txt)
P.write_bytes(content)
print('Created',len(slides),'slides',P)
